import { createLearningService, validateExerciseSet, resolveTextAnchor, inferPdfOutline, validateOutlineProposal, readImageDimensions, LEARNING_LIMITS } from '../learning/services.mjs';

function syntheticPdf(pages) {
  const objects = [null, '<< /Type /Catalog /Pages 2 0 R >>', `<< /Type /Pages /Kids [${pages.map((_,i)=>`${4+i*2} 0 R`).join(' ')}] /Count ${pages.length} >>`, '<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>'];
  pages.forEach((lines,i)=>{ const stream='BT /F1 12 Tf 40 800 Td '+lines.map((line,n)=>(n?'0 -22 Td ':'')+`(${line.replace(/[\\()]/g,'\\$&')}) Tj`).join('\n')+' ET'; objects.push(`<< /Type /Page /Parent 2 0 R /MediaBox [0 0 612 842] /Resources << /Font << /F1 3 0 R >> >> /Contents ${5+i*2} 0 R >>`);objects.push(`<< /Length ${Buffer.byteLength(stream)} >>\nstream\n${stream}\nendstream`); });
  let output='%PDF-1.4\n', offsets=[0]; for(let i=1;i<objects.length;i++){offsets.push(Buffer.byteLength(output));output+=`${i} 0 obj\n${objects[i]}\nendobj\n`;}
  const xref=Buffer.byteLength(output);output+=`xref\n0 ${objects.length}\n0000000000 65535 f \n`+offsets.slice(1).map(n=>String(n).padStart(10,'0')+' 00000 n \n').join('')+`trailer\n<< /Size ${objects.length} /Root 1 0 R >>\nstartxref\n${xref}\n%%EOF\n`;return Buffer.from(output);
}
const PDF_PAGES=[['Contents','Chapter 1: Fractions ........ 2','1.1 Equal parts ........ 2','1.2 Adding fractions ........ 3','Chapter 2: Photosynthesis ........ 4','2.1 Inputs and outputs ........ 4','2.2 Testing predictions ........ 5'],['Chapter 1: Fractions','1.1 Equal parts','A fraction describes equal parts of a whole.','EXACT_SOURCE_FRACTION_21'],['1.2 Adding fractions','Add numerators and keep the denominator.','EXACT_SOURCE_FRACTION_32'],['Chapter 2: Photosynthesis','2.1 Inputs and outputs','Plants use light, water and carbon dioxide.','EXACT_SOURCE_PLANT_43'],['2.2 Testing predictions','Keep water supply the same.','EXACT_SOURCE_PLANT_54']];
function mockModel({messages}) { const inputs=messages.filter(v=>v.role==='user').map(v=>{try{return JSON.parse(v.content);}catch{return null;}}).filter(Boolean), input=inputs.find(v=>v.task)||inputs.find(v=>v.sourcePages)||inputs.find(v=>v.sources); const sourceId=input.sources?.[0]?.id;
  if(input.task==='grade')return Promise.resolve(JSON.stringify({feedback:'AI suggestion: review the precision of your explanation.',questions:input.questions.map(q=>({questionId:q.id,score:4,maxScore:5,feedback:'Connect your explanation explicitly to the provided source.',sourceIds:[sourceId]}))}));
  if(input.sourcePages)return Promise.resolve(JSON.stringify({chapters:[{title:'Private course',startPage:1,endPage:5,knowledgePoints:[{title:'Fraction evidence',startPage:2,endPage:3,sourcePages:[2,3]}]}]}));
  if(input.task==='exercises')return Promise.resolve(JSON.stringify({questions:Array.from({length:input.count},()=>input.format.includes('"choice"')?{type:'choice',stem:'Which part?',options:['One half','One third'],answer:'A',explanation:'Based on the provided source.',sourceIds:[sourceId]}:{type:'short',stem:'Explain a fraction.',answer:'Equal parts of a whole.',rubric:['Mentions equal parts'],explanation:'Based on source.',sourceIds:[sourceId]})}));
  return Promise.resolve(JSON.stringify({title:'Source lesson',content:'A fraction describes equal parts. This is a mock-generated test response.',sourceIds:[sourceId]}));
}
async function harness(t,options={}) { const directory=await mkdtemp(path.join(os.tmpdir(),'mentrix-service-')),store=createStudyStore({dataDir:directory});await store.mutate(s=>{s.textbooks.push({id:'book-one',userId:'user-one',title:'Synthetic',createdAt:new Date().toISOString(),updatedAt:new Date().toISOString()},{id:'book-other',userId:'user-two',title:'Other',createdAt:new Date().toISOString(),updatedAt:new Date().toISOString()});s.workshops.push({id:'work-one',userId:'user-one',title:'Materials',createdAt:new Date().toISOString(),updatedAt:new Date().toISOString()});s.conversations.push({id:'conv-one',userId:'user-one',textbookId:'book-one',createdAt:new Date().toISOString(),updatedAt:new Date().toISOString()});});const service=createLearningService({store,dataDir:directory,model:mockModel,...options});const server=http.createServer(async(req,res)=>{try{if(!await service.handle(req,res,new URL(req.url,'http://local').pathname,{id:req.headers['x-user']||'user-one'})){res.writeHead(404);res.end();}}catch(e){res.writeHead(e.status||500,{'Content-Type':'application/json'});res.end(JSON.stringify({success:false,error_code:e.code,message:e.message}));}});await new Promise(resolve=>server.listen(0,'127.0.0.1',resolve));const origin='http://127.0.0.1:'+server.address().port;
  t.after(async()=>{await service.close();await new Promise(resolve=>server.close(resolve));const resolved=path.resolve(directory);assert.equal(path.dirname(resolved),path.resolve(os.tmpdir()));assert.ok(path.basename(resolved).startsWith('mentrix-service-'));await rm(resolved,{recursive:true,force:true});});
  const request=async(route,{method='GET',body,user,raw,name}={})=>{const response=await fetch(origin+'/api/v1'+route,{method,headers:{...(body!==undefined?{'Content-Type':'application/json'}:{}),...(user?{'X-User':user}:{}),...(raw?{'Content-Type':'application/octet-stream','X-File-Name':encodeURIComponent(name||'own.md')}: {})},body:raw|| (body!==undefined?JSON.stringify(body):undefined)});const content=await response.text();let data;try{data=JSON.parse(content);}catch{data=content;}return{status:response.status,...(typeof data==='object'?data:{text:data})};};
  const wait=async(id)=>{for(let i=0;i<1500;i++){const response=await request('/jobs/'+id);if(response.status!==200)throw new Error('Job disappeared');if(!['queued','running','cancelling'].includes(response.data.status))return response.data;await new Promise(resolve=>setTimeout(resolve,20));}throw new Error('Job did not settle');};
  const parsed=async(raw=Buffer.from('# Fractions\nA fraction describes equal parts.\n\n# Plants\nPlants use light and water.'),name='own.md')=>{const file=await request('/textbooks/book-one/files',{method:'POST',raw,name});assert.equal(file.status,201,JSON.stringify(file));const job=await request('/textbooks/book-one/parse',{method:'POST',body:{}});assert.equal(job.status,202);const done=await wait(job.data.id);assert.equal(done.status,'completed',JSON.stringify(done));return{file:file.data,outline:(await request('/textbooks/book-one/outline')).data};};
  const restart=async()=>{await service.close();const replacement=createLearningService({store:createStudyStore({dataDir:directory}),dataDir:directory,model:mockModel,...options});service.handle=replacement.handle;service.close=replacement.close;};
  return{request,wait,parsed,store,directory,service,origin,restart};
}

test('real PDF text and visible TOC produce page-bound stable chapter/knowledge identities',async t=>{const h=await harness(t);const {file,outline}=await h.parsed(syntheticPdf(PDF_PAGES),'synthetic.pdf');assert.equal(outline.chapters.length,2);assert.equal(outline.knowledgePoints.length,4);const kp=outline.knowledgePoints.find(v=>v.title.includes('Equal parts'));assert.deepEqual([kp.sourceAnchor.startPage,kp.sourceAnchor.endPage],[2,2]);assert.match((await h.request('/knowledge-points/'+kp.id)).data.sourceText,/EXACT_SOURCE_FRACTION_21/);assert.ok(!(await h.request('/knowledge-points/'+kp.id)).data.sourceText.includes('PLANT_43'));const fileContent=await h.request('/files/'+file.id+'/content?page=4');assert.match(fileContent.data.page.text,/PLANT_43/);const again=await h.request('/textbooks/book-one/parse',{method:'POST',body:{}});assert.equal((await h.wait(again.data.id)).status,'completed');assert.deepEqual((await h.request('/textbooks/book-one/outline')).data.knowledgePoints.map(v=>v.id),outline.knowledgePoints.map(v=>v.id));assert.equal((await h.request('/files/'+file.id+'/content',{user:'user-two'})).status,404);});

test('source lesson, private follow-up, exercise attempt/reveal, notes and export form one durable path',async t=>{const h=await harness(t),{outline}=await h.parsed(),kp=outline.knowledgePoints[0];const lesson=await h.request('/knowledge-points/'+kp.id+'/lesson',{method:'POST',body:{}});assert.equal((await h.wait(lesson.data.id)).status,'completed');const lessons=(await h.request('/knowledge-points/'+kp.id+'/lesson')).data.items;assert.equal(lessons[0].sourceIds[0],kp.id);assert.equal((await h.request('/knowledge-points/'+kp.id+'/lesson',{user:'user-two'})).status,404);
  const chat=await h.request('/conversations/conv-one/messages',{method:'POST',body:{content:'Explain this again',knowledgePointId:kp.id}});assert.equal((await h.wait(chat.data.id)).status,'completed');assert.equal((await h.request('/conversations/conv-one/messages')).data.items.filter(v=>v.role==='assistant').length,1);
  const exerciseJob=await h.request('/knowledge-points/'+kp.id+'/exercises',{method:'POST',body:{type:'choice',count:2}});const done=await h.wait(exerciseJob.data.id);assert.equal(done.status,'completed');assert.ok(!JSON.stringify(done).includes('answer'));const set=(await h.request('/knowledge-points/'+kp.id+'/exercises')).data.items[0];assert.ok(set.questions.every(q=>!('answer'in q)&&!('explanation'in q)));
  const answers=Object.fromEntries(set.questions.map(q=>[q.id,'A']));const first=await h.request('/exercises/'+set.id+'/attempts',{method:'POST',body:{answers,clientAttemptId:'retry-one'}}),second=await h.request('/exercises/'+set.id+'/attempts',{method:'POST',body:{answers,clientAttemptId:'retry-one'}});assert.equal(first.data.id,second.data.id);assert.equal((await h.store.snapshot()).attempts.length,1);const reveal=await h.request('/attempts/'+first.data.id+'/reveal',{method:'POST',body:{}});assert.ok(reveal.data.questions.every(q=>q.correct===true));assert.equal((await h.request('/attempts/'+first.data.id+'/reveal',{method:'POST',body:{},user:'user-two'})).status,404);
  const note=await h.request('/highlights',{method:'POST',body:{sourceId:kp.id,revision:kp.revision,exact:'A fraction',note:'Review later'}});assert.equal(note.status,201);assert.equal((await h.request('/highlights')).data.items[0].resolution.status,'resolved');assert.equal((await h.request('/knowledge-points/'+kp.id+'/progress',{method:'PATCH',body:{status:'mastered'}})).data.progress,'mastered');const artifact=await h.request('/textbooks/book-one/artifacts',{method:'POST',body:{}});assert.equal(artifact.status,201);assert.match((await h.request('/artifacts/'+artifact.data.id+'/download')).text,/Source lesson|fraction/);assert.equal((await h.request('/artifacts/'+artifact.data.id+'/download',{user:'user-two'})).status,404);});

test('bad JSON, nonexistent citations and unconfigured provider never create a ready lesson',async t=>{for(const response of ['not-json','',JSON.stringify({title:'x',content:'fabricated',sourceIds:['foreign']})]){const h=await harness(t,{model:async()=>response});const {outline}=await h.parsed(),kp=outline.knowledgePoints[0],job=await h.request('/knowledge-points/'+kp.id+'/lesson',{method:'POST',body:{}});assert.equal((await h.wait(job.data.id)).status,'failed');assert.equal((await h.store.snapshot()).lessons.length,0);assert.ok((await h.store.snapshot()).ledger.filter(v=>v.units).every(v=>v.status==='released'));}const h=await harness(t,{model:undefined}),{outline}=await h.parsed();assert.equal((await h.request('/knowledge-points/'+outline.knowledgePoints[0].id+'/lesson',{method:'POST',body:{}})).status,503);});

test('cancel ignored-by-provider work, resume explicitly, and reject late source writes',async t=>{let release,started;const running=new Promise(resolve=>started=resolve);let calls=0;const h=await harness(t,{model:async args=>{calls++;started();return await new Promise(resolve=>{release=()=>mockModel(args).then(resolve);});}}),{outline}=await h.parsed(),kp=outline.knowledgePoints[0];const request=await h.request('/knowledge-points/'+kp.id+'/lesson',{method:'POST',body:{}});await running;assert.equal((await h.request('/jobs/'+request.data.id+'/cancel',{method:'POST',body:{}})).status,200);assert.equal((await h.wait(request.data.id)).status,'cancelled');release();await new Promise(resolve=>setTimeout(resolve,30));assert.equal((await h.store.snapshot()).lessons.length,0);const resumed=await h.request('/jobs/'+request.data.id+'/resume',{method:'POST',body:{}});await new Promise(resolve=>setTimeout(resolve,30));await h.store.mutate(s=>{s.knowledgePoints.find(v=>v.id===kp.id).revision++;});release();assert.equal((await h.wait(resumed.data.id)).error.code,'STALE_SOURCE');assert.equal((await h.store.snapshot()).lessons.length,0);assert.equal(calls,2);});

test('structure proposal is validated and waits for manual confirmation',async t=>{const h=await harness(t),{outline}=await h.parsed(syntheticPdf(PDF_PAGES),'course.pdf');const job=await h.request('/textbooks/book-one/structure',{method:'POST',body:{}});const done=await h.wait(job.data.id);assert.equal(done.status,'completed');const proposal=(await h.request('/artifacts/'+done.result.id)).data;assert.equal(proposal.requiresConfirmation,true);assert.deepEqual((await h.request('/textbooks/book-one/outline')).data.chapters.map(v=>v.id),outline.chapters.map(v=>v.id));assert.equal((await h.request('/textbooks/book-one/outline',{method:'PATCH',body:{chapters:proposal.chapters}})).data.knowledgePoints.length,1);assert.throws(()=>validateOutlineProposal({chapters:[{title:'x',startPage:1,endPage:3001,knowledgePoints:[]}]},1,5),/来源/);});

test('lesson-specific highlights and textbook knowledge-point conversations retain their versions',async t=>{const h=await harness(t),{outline}=await h.parsed(),kp=outline.knowledgePoints[0];const generated=await h.request('/knowledge-points/'+kp.id+'/lesson',{method:'POST',body:{}});const lessonId=(await h.wait(generated.data.id)).result.id;const conversation=await h.request('/textbooks/book-one/conversations',{method:'POST',body:{knowledgePointId:kp.id}});assert.equal(conversation.status,201);assert.equal((await h.request('/textbooks/book-one/conversations?knowledgePointId='+kp.id)).data.items.length,1);const note=await h.request('/highlights',{method:'POST',body:{sourceId:kp.id,sourceKind:'lesson',lessonId,revision:kp.revision,exact:'mock-generated test response',note:'Only in the lecture'}});assert.equal(note.status,201);assert.equal((await h.request('/highlights')).data.items[0].resolution.status,'resolved');await h.store.mutate(s=>{s.knowledgePoints.find(v=>v.id===kp.id).revision++;});assert.equal((await h.request('/highlights')).data.items[0].resolution.status,'stale');assert.equal(resolveTextAnchor('same same',{exact:'same'}).status,'ambiguous');});

test('parallel generation assigns unique committed versions and daily budget is enforced',async t=>{const h=await harness(t,{model:async args=>{await new Promise(resolve=>setTimeout(resolve,30));return mockModel(args);},maxDailyUnits:2}),{outline}=await h.parsed(),kp=outline.knowledgePoints[0];const [one,two]=await Promise.all([h.request('/knowledge-points/'+kp.id+'/lesson',{method:'POST',body:{}}),h.request('/knowledge-points/'+kp.id+'/lesson',{method:'POST',body:{}})]);assert.equal(one.status,202);assert.equal(two.status,202);assert.equal((await h.wait(one.data.id)).status,'completed');assert.equal((await h.wait(two.data.id)).status,'completed');assert.deepEqual((await h.request('/knowledge-points/'+kp.id+'/lesson')).data.items.map(v=>v.version).sort(),[1,2]);assert.equal((await h.request('/knowledge-points/'+kp.id+'/lesson',{method:'POST',body:{}})).status,429);});

test('full daily budget cannot be bypassed by negative OCR units or malformed parse options',async t=>{const h=await harness(t,{maxDailyUnits:1}),{outline}=await h.parsed();const lesson=await h.request('/knowledge-points/'+outline.knowledgePoints[0].id+'/lesson',{method:'POST',body:{}});assert.equal((await h.wait(lesson.data.id)).status,'completed');const before=await h.store.snapshot();
  for(const body of [{ocr:true,ocrPages:-100},{ocr:'true',ocrPages:1},{ocr:true,ocrPages:0},{ocr:true,ocrPages:1.5},{ocr:true,ocrPages:6},{ocr:true,ocrPages:null},{ocr:true,startPage:0},{ocr:true,startPage:5,endPage:3},{ocr:true,ocrPages:1,startPage:1,endPage:2},[],null]){const response=await h.request('/textbooks/book-one/parse',{method:'POST',body});assert.equal(response.status,400,JSON.stringify({body,response}));const state=await h.store.snapshot();assert.equal(state.jobs.length,before.jobs.length);assert.equal(state.ledger.length,before.ledger.length);assert.ok(state.ledger.every(v=>Number.isSafeInteger(v.units)&&v.units>=0));}
  assert.equal((await h.request('/knowledge-points/'+outline.knowledgePoints[0].id+'/lesson',{method:'POST',body:{}})).status,429);
});
test('submitted attempts reload after a store restart without exposing answer keys to either user',async t=>{
  const h=await harness(t),{outline}=await h.parsed(),kp=outline.knowledgePoints[0],generated=await h.request('/knowledge-points/'+kp.id+'/exercises',{method:'POST',body:{type:'short',count:1}});assert.equal((await h.wait(generated.data.id)).status,'completed');const set=(await h.request('/knowledge-points/'+kp.id+'/exercises')).data.items[0],attempt=await h.request('/exercises/'+set.id+'/attempts',{method:'POST',body:{clientAttemptId:'persist-short',answers:{[set.questions[0].id]:'My private submitted explanation'}}});assert.equal((await h.request('/exercises/'+set.id+'/attempts')).data.items[0].id,attempt.data.id);await h.restart();const restored=await h.request('/attempts/'+attempt.data.id);assert.equal(restored.status,200);assert.equal(restored.data.answers[set.questions[0].id],'My private submitted explanation');assert.equal(restored.data.revealedAt,null);assert.ok(!JSON.stringify(restored).includes('Equal parts of a whole.'));assert.equal((await h.request('/attempts/'+attempt.data.id,{user:'user-two'})).status,404);assert.equal((await h.request('/exercises/'+set.id+'/attempts',{user:'user-two'})).status,404);await h.request('/attempts/'+attempt.data.id+'/reveal',{method:'POST',body:{}});await h.restart();assert.ok((await h.request('/attempts/'+attempt.data.id)).data.revealedAt);assert.ok(!JSON.stringify((await h.request('/attempts/'+attempt.data.id)).data).includes('Equal parts of a whole.'));
});
