test('AI short-answer grading updates one attempt, remains reviewable and keeps answer keys behind reveal',async t=>{
  const h=await harness(t),{attempt}=await shortAttempt(h),task=await h.request('/attempts/'+attempt.id+'/grade',{method:'POST',body:{}});assert.equal(task.status,202);const done=await h.wait(task.data.id);assert.equal(done.status,'completed');assert.deepEqual(done.result,{id:attempt.id,collection:'attempts'});const result=(await h.request('/attempts/'+attempt.id)).data;assert.equal(result.status,'graded');assert.equal(result.grading.score,8);assert.equal(result.grading.maxScore,10);assert.equal(result.grading.requiresHumanReview,true);assert.equal(result.grading.method,'ai-suggested');assert.equal(result.revealedAt,null);assert.ok(!JSON.stringify(result).includes('Equal parts of a whole.'));assert.equal((await h.store.snapshot()).attempts.length,1);assert.equal((await h.request('/attempts/'+attempt.id+'/grade',{method:'POST',body:{},user:'user-two'})).status,404);await h.restart();assert.equal((await h.request('/attempts/'+attempt.id)).data.grading.score,8);
});
test('bad grading JSON or invalid scores release budget, keep ungraded state and permit explicit retry',async t=>{
  let mode='normal';const provider=async args=>{const input=args.messages.find(v=>v.role==='user'&&v.content.includes('"task":"grade"'));if(!input)return mockModel(args);if(mode==='bad')return'not-json';const output=JSON.parse(await mockModel(args));if(mode==='score')output.questions[0].score=99;if(mode==='foreign')output.questions[0].questionId='someone-elses-question';return JSON.stringify(output);};const h=await harness(t,{model:provider}),{attempt}=await shortAttempt(h);
  for(mode of ['bad','score','foreign']){const task=await h.request('/attempts/'+attempt.id+'/grade',{method:'POST',body:{}}),done=await h.wait(task.data.id);assert.equal(done.status,'failed');const value=(await h.request('/attempts/'+attempt.id)).data;assert.equal(value.status,'failed');assert.ok(!value.grading);assert.equal((await h.store.snapshot()).ledger.find(v=>v.jobId===task.data.id).status,'released');}
  mode='normal';const retry=await h.request('/attempts/'+attempt.id+'/grade',{method:'POST',body:{}});assert.equal((await h.wait(retry.data.id)).status,'completed');assert.equal((await h.store.snapshot()).attempts.length,1);
});
