  const provider=async args=>mockModel(args),h=await harness(t,{model:provider}),{attempt}=await shortAttempt(h);provider.configured=false;const before=await h.store.snapshot();assert.equal((await h.request('/attempts/'+attempt.id+'/grade',{method:'POST',body:{}})).status,503);const after=await h.store.snapshot();assert.equal(after.jobs.length,before.jobs.length);assert.equal(after.ledger.length,before.ledger.length);provider.configured=true;const kp=(await h.request('/textbooks/book-one/outline')).data.knowledgePoints[0],task=await h.request('/knowledge-points/'+kp.id+'/exercises',{method:'POST',body:{type:'choice',count:1}});assert.equal((await h.wait(task.data.id)).status,'completed');const exercise=(await h.request('/knowledge-points/'+kp.id+'/exercises')).data.items.at(-1),choice=(await h.request('/exercises/'+exercise.id+'/attempts',{method:'POST',body:{clientAttemptId:'choice-grade',answers:{[exercise.questions[0].id]:'A'}}})).data;provider.configured=false;const graded=await h.request('/attempts/'+choice.id+'/grade',{method:'POST',body:{}});assert.equal(graded.status,202);assert.equal((await h.wait(graded.data.id)).status,'completed');const value=(await h.request('/attempts/'+choice.id)).data;assert.equal(value.grading.score,1);assert.equal(value.grading.requiresHumanReview,false);assert.equal(value.grading.method,'deterministic-choice');
