  const fallback=resolveTextAnchor(REPEATED_LESSON,DOM_ANCHOR);assert.equal(fallback.status,'resolved');assert.equal(fallback.start,REPEATED_LESSON.lastIndexOf(DOM_ANCHOR.exact));assert.equal(fallback.requiresReview,true);assert.equal(fallback.strategy,'occurrence-fallback');
  const unique=resolveTextAnchor('A\nsame\n\nB\nsame\n\nC',{exact:'same',prefix:'B\n',suffix:'\n\nC',occurrence:1});assert.equal(unique.status,'resolved');assert.equal(unique.start,10);assert.equal(unique.strategy,'context');assert.ok(!unique.requiresReview);
