test('offline HTML artifacts preserve owner guards and export references only from revealed attempts',async t=>{
  let calls=0;const provider=async args=>{calls++;const value=JSON.parse(await mockModel(args));if(value.questions?.[0]?.type==='short')for(const q of value.questions){q.answer='PRIVATE_REFERENCE_KEY_9077';q.explanation='PRIVATE_SOLUTION_MARKER_8821';}return JSON.stringify(value);},h=await harness(t,{model:provider}),{attempt,kp}=await shortAttempt(h),grade=await h.request('/attempts/'+attempt.id+'/grade',{method:'POST',body:{}});assert.equal((await h.wait(grade.data.id)).status,'completed');const first=await h.request('/textbooks/book-one/artifacts',{method:'POST',body:{knowledgePointIds:[kp.id]}});assert.equal(first.status,201);assert.match(first.data.content,/My own incomplete explanation/);assert.match(first.data.content,/AI建议分/);assert.ok(!first.data.content.includes('PRIVATE_REFERENCE_KEY_9077'));assert.ok(!first.data.content.includes('PRIVATE_SOLUTION_MARKER_8821'));const before=calls,response=await fetch(h.origin+'/api/v1/artifacts/'+first.data.id+'/download?format=html');assert.equal(response.status,200);assert.match(response.headers.get('content-type'),/^text\/html/);assert.match(response.headers.get('content-disposition'),/\.html/);const html=await response.text();assert.match(html,/Content-Security-Policy/);assert.ok(!html.includes('PRIVATE_REFERENCE_KEY_9077'));assert.equal(calls,before);assert.equal((await h.request('/artifacts/'+first.data.id+'/download?format=html',{user:'user-two'})).status,404);assert.equal((await h.request('/artifacts/'+first.data.id+'/download?format=pdf')).status,400);await h.request('/attempts/'+attempt.id+'/reveal',{method:'POST',body:{}});const second=await h.request('/textbooks/book-one/artifacts',{method:'POST',body:{knowledgePointIds:[kp.id]}});assert.match(second.data.content,/PRIVATE_REFERENCE_KEY_9077/);assert.match(second.data.content,/PRIVATE_SOLUTION_MARKER_8821/);assert.ok(!(await h.request('/artifacts/'+first.data.id+'/download')).text.includes('PRIVATE_REFERENCE_KEY_9077'));assert.equal(calls,before);await h.store.mutate(s=>{s.textbooks=s.textbooks.filter(v=>v.id!=='book-one');});assert.equal((await h.request('/artifacts/'+second.data.id+'/download?format=html')).status,404);
});

function pngHeader(width,height){const bytes=Buffer.alloc(33);Buffer.from([137,80,78,71,13,10,26,10]).copy(bytes);bytes.writeUInt32BE(13,8);bytes.write('IHDR',12);bytes.writeUInt32BE(width,16);bytes.writeUInt32BE(height,20);bytes[24]=8;bytes[25]=2;return bytes;}
test('image dimensions are read from PNG/JPEG/WebP headers before decoding',async()=>{
  const {createCanvas}=await import('@napi-rs/canvas'),canvas=createCanvas(64,48);canvas.getContext('2d').fillRect(0,0,64,48);
  for(const mime of ['image/png','image/jpeg','image/webp'])assert.deepEqual(readImageDimensions(canvas.toBuffer(mime),mime),{width:64,height:48});
  assert.throws(()=>readImageDimensions(pngHeader(4000,4000),'image/png'),e=>e.code==='IMAGE_PIXELS');assert.throws(()=>readImageDimensions(pngHeader(5000,1),'image/png'),e=>e.code==='IMAGE_PIXELS');
  const jpeg=Buffer.from([255,216,255,192,0,11,8,0,16,19,136,1,1,17,0,255,217]);assert.throws(()=>readImageDimensions(jpeg,'image/jpeg'),e=>e.code==='IMAGE_PIXELS');
  assert.throws(()=>readImageDimensions(Buffer.from([255,216,255,217]),'image/jpeg'),e=>e.code==='IMAGE_DIMENSIONS');
});
test('HTTP workshop giant image headers and damaged small images cannot enter an OCR worker',async t=>{
  let workers=0;const h=await harness(t,{onOcrWorkerStart:()=>{workers++;}});
  for(const [name,raw,expected]of [['huge.png',pngHeader(100000,100000),'IMAGE_PIXELS'],['wide.jpg',Buffer.from([255,216,255,192,0,11,8,0,16,19,136,1,1,17,0,255,217]),'IMAGE_PIXELS'],['damaged.png',pngHeader(32,32),'IMAGE_DECODE']]){
    const uploaded=await h.request('/workshops/work-one/files',{method:'POST',raw,name});assert.equal(uploaded.status,201);const task=await h.request('/workshops/work-one/files/'+uploaded.data.id+'/parse',{method:'POST',body:{ocrLanguage:'eng'}}),done=await h.wait(task.data.id);assert.equal(done.status,'failed');assert.equal(done.error.code,expected,JSON.stringify(done));assert.equal(workers,0);
  }
  const state=await h.store.snapshot();assert.ok(state.fileRecords.every(v=>v.status==='uploaded'));assert.ok(state.ledger.filter(v=>v.units).every(v=>v.units===1&&v.status==='released'));
});
test('optional actual small workshop PNG OCR honors the same private local-language path',async t=>{
  const language=path.resolve('.local/learning/ocr-langs/eng.traineddata');try{await access(language);}catch{t.skip('Optional local English OCR language package not present');return;}let workers=0;const h=await harness(t,{onOcrWorkerStart:()=>{workers++;}});await mkdir(path.join(h.directory,'ocr-langs'));await copyFile(language,path.join(h.directory,'ocr-langs/eng.traineddata'));
  const{createCanvas}=await import('@napi-rs/canvas'),canvas=createCanvas(900,160),ctx=canvas.getContext('2d');ctx.fillStyle='white';ctx.fillRect(0,0,900,160);ctx.fillStyle='black';ctx.font='34px Arial';ctx.fillText('PRIVATE WORKSHOP TEST',30,55);ctx.fillText('Water evaporates from the surface.',30,115);
  const uploaded=await h.request('/workshops/work-one/files',{method:'POST',raw:canvas.toBuffer('image/png'),name:'synthetic-small.png'});assert.equal(uploaded.status,201);const task=await h.request('/workshops/work-one/files/'+uploaded.data.id+'/parse',{method:'POST',body:{ocrLanguage:'eng'}}),done=await h.wait(task.data.id);assert.equal(done.status,'completed',JSON.stringify(done));assert.equal(workers,1);const file=(await h.store.snapshot()).fileRecords.find(v=>v.id===uploaded.data.id);assert.match(file.pages[0].text,/Water evaporates/i);assert.equal(file.method,'local-ocr');
});

test('optional actual local OCR of synthetic scan uses private offline language data',async t=>{const fixture=path.resolve('.collab/mentrix/evidence/reviewer-fixtures/scanned.pdf'),language=path.resolve('.local/learning/ocr-langs/eng.traineddata');try{await access(fixture);await access(language);}catch{t.skip('Optional reviewer scan/local English language package not present');return;}const h=await harness(t);await mkdir(path.join(h.directory,'ocr-langs'));await copyFile(language,path.join(h.directory,'ocr-langs/eng.traineddata'));await h.request('/textbooks/book-one/files',{method:'POST',raw:await readFile(fixture),name:'synthetic-scan.pdf'});const job=await h.request('/textbooks/book-one/parse',{method:'POST',body:{ocr:true,ocrPages:1,ocrLanguage:'eng'}});const done=await h.wait(job.data.id);assert.equal(done.status,'completed',JSON.stringify(done));const file=(await h.store.snapshot()).fileRecords[0];assert.match(file.pages[0].text,/evaporates|condenses/i);assert.equal(file.method,'pdf-text-and-local-ocr');});
